update public.bots
set strategy_description = E'- Mercado e histórico: XAUUSD no M5, com pelo menos 23 candles para avaliar o setup.\n- Rompimento: o candle fecha acima da máxima — ou abaixo da mínima — dos 20 candles anteriores e tem corpo maior que a média dos 10 candles anteriores.\n- Pullback: o preço retesta o nível rompido com volume não superior à média recente.\n- Entrada: só é validada por candle de ignição na direção do rompimento, superando a máxima ou mínima do pullback e com volume acima da média dos 20 candles anteriores.\n- Filtros: ativo, timeframe e spread máximo precisam estar dentro da configuração do bot.\n- Stop: além do último fractal contrário de cinco candles, com buffer de 1 ATR(14).\n- Alvo e risco: risco/retorno mínimo de 1:1,5 e tamanho sugerido pelo risco por operação configurado (5% por padrão).\n- Execução: permanece bloqueada até a habilitação explícita de decisões ao vivo.'
where id = 'bot-1';
